import { coverLetterContext } from "@ai-job-apply/ai-sdk";
import type { CoverLetterEvidenceSource } from "@ai-job-apply/documents-service/cover-letter-runtime";
import {
  type NativeEvidenceBinding,
  nativeEvidenceBinding,
} from "@ai-job-apply/documents-service/native-evidence-binding";
import { createOwnedCoverLetterEvidenceSource } from "./application-preparation-evidence.js";

/** Original facts/job only, through owner APIs. No generated bytes, provider, raw resume,
 * control issuance or listener. SQL admission callbacks must release before owner reads.
 * Caller IAM, private transport and managed composition remain activation requirements. */
export function createNativeOwnedCoverLetterEvidenceSource(
  options: Parameters<typeof createOwnedCoverLetterEvidenceSource>[0] & {
    binding: NativeEvidenceBinding;
    context: { jobContextHash: string; confirmedFactsHash: string };
    checkAdmission(binding: Readonly<NativeEvidenceBinding>): Promise<void>;
  },
): CoverLetterEvidenceSource {
  const binding = nativeEvidenceBinding(options.binding);
  const keys = ["jobContextHash", "confirmedFactsHash"];
  if (
    Object.getPrototypeOf(options.context) !== Object.prototype ||
    Reflect.ownKeys(options.context).length !== keys.length ||
    !keys.every((key) => {
      const descriptor = Object.getOwnPropertyDescriptor(options.context, key);
      return descriptor?.enumerable === true && "value" in descriptor;
    })
  )
    throw Error("NativeEvidenceUnavailable");
  const context = Object.freeze({ ...options.context });
  if (
    !/^[a-f0-9]{64}$/u.test(context.jobContextHash) ||
    !/^[a-f0-9]{64}$/u.test(context.confirmedFactsHash)
  )
    throw Error("NativeEvidenceUnavailable");
  const enabled = options.enabled ?? (() => false);
  const admission = options.checkAdmission;
  const source = createOwnedCoverLetterEvidenceSource(options);
  let active = false;
  return Object.freeze({
    async load(ownerUserId: string, applicationId: string) {
      let result: Awaited<ReturnType<CoverLetterEvidenceSource["load"]>> | undefined;
      if (active) throw Error("NativeEvidenceUnavailable");
      active = true;
      try {
        if (
          !enabled() ||
          ownerUserId !== binding.scope.ownerUserId ||
          applicationId !== binding.scope.applicationId
        )
          throw Error();
        await admission(binding);
        if (!enabled()) throw Error();
        result = structuredClone(await source.load(ownerUserId, applicationId));
        if (!enabled()) throw Error();
        const current = coverLetterContext({ ...result, now: new Date() });
        if (
          current.jobContextHash !== context.jobContextHash ||
          current.confirmedFactsHash !== context.confirmedFactsHash
        )
          throw Error();
        await admission(binding);
        if (!enabled()) throw Error();
        const detached = structuredClone(result);
        return detached;
      } catch {
        throw Error("NativeEvidenceUnavailable");
      } finally {
        // Clear this owned intermediate after refusal or transfer; returned detached facts
        // remain the dedicated actor's responsibility. No claim of zeroizing JS strings.
        if (result) {
          for (const fact of result.facts) fact.value = "";
          result.job.title = "";
          result.job.company = "";
          result.job.description = "";
        }
        active = false;
      }
    },
  });
}
